            '                   feFbm(vec2(uv.x * 8.5 - uTime * 0.35, uv.y * 3.2 - uTime * speed * 0.85)));',
            '  float n = feFbm(vec2(uv.x * 9.5 + (warp.x - 0.5) * 1.6, uv.y * 3.4 - uTime * speed + (warp.y - 0.5) * 1.2));',
            '  float detail = feNoise(vec2(uv.x * 22.0, uv.y * 9.0 - uTime * (speed * 1.6)));',
