            'uniform float uTime;',
            'uniform float uFireActive;',
            'uniform float uSeverity;',
            'uniform float uWildfire;',
            'uniform float uPatchy;',
            'uniform float uHC;',
            'varying vec2 vUv;',
            'varying float vWorldX;',
