            '  float billow = smoothstep(0.28, 0.78, n1 * 0.58 + n2 * 0.42);',
            '  float vMask = smoothstep(0.0, 0.22, uv.y) * smoothstep(1.0, 0.28, uv.y);',
            '  float hMask = smoothstep(0.0, 0.10, uv.x) * smoothstep(1.0, 0.90, uv.x);',
